     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Tetris</title>
     7	<style>
     8	  :root {
     9	    --cell: 28px;
    10	    --bg: #14161c;
    11	    --panel: #1d2029;
    12	    --grid: #262a35;
    13	    --text: #e8eaf0;
    14	    --muted: #8a90a0;
    15	  }
    16	  * { box-sizing: border-box; }
    17	  body {
    18	    margin: 0;
    19	    min-height: 100vh;
    20	    display: flex;
    21	    align-items: center;
    22	    justify-content: center;
    23	    background: var(--bg);
    24	    color: var(--text);
    25	    font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    26	  }
    27	  .game {
    28	    display: flex;
    29	    gap: 20px;
    30	    align-items: flex-start;
    31	    padding: 16px;
    32	  }
    33	  .board {
    34	    display: grid;
    35	    grid-template-columns: repeat(10, var(--cell));
    36	    grid-template-rows: repeat(20, var(--cell));
    37	    gap: 1px;
    38	    padding: 1px;
    39	    background: var(--grid);
    40	    border: 2px solid #3a3f4d;
    41	    border-radius: 4px;
    42	    position: relative;
    43	  }
    44	  .cell { background: var(--bg); }
    45	  .side {
    46	    display: flex;
    47	    flex-direction: column;
    48	    gap: 12px;
    49	    min-width: 140px;
    50	  }
    51	  .box {
    52	    background: var(--panel);
    53	    border-radius: 6px;
    54	    padding: 10px 12px;
    55	  }
    56	  .label {
    57	    font-size: 11px;
    58	    text-transform: uppercase;
    59	    letter-spacing: 0.08em;
    60	    color: var(--muted);
    61	  }
    62	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
    63	  .preview {
    64	    display: grid;
    65	    grid-template-columns: repeat(4, 18px);
    66	    grid-template-rows: repeat(2, 18px);
    67	    gap: 1px;
    68	    margin-top: 8px;
    69	  }
    70	  .preview .mini { background: transparent; }
    71	  .help { color: var(--muted); font-size: 12px; }
    72	  .help kbd {
    73	    background: #2b2f3a;
    74	    border-radius: 3px;
    75	    padding: 0 4px;
    76	    font: inherit;
    77	    color: var(--text);
    78	  }
    79	  .overlay {
    80	    position: absolute;
    81	    inset: 0;
    82	    display: flex;
    83	    flex-direction: column;
    84	    align-items: center;
    85	    justify-content: center;
    86	    gap: 10px;
    87	    background: rgba(10, 11, 15, 0.78);
    88	    font-size: 20px;
    89	    font-weight: 600;
    90	  }
    91	  .overlay button {
    92	    font: inherit;
    93	    font-size: 14px;
    94	    padding: 6px 14px;
    95	    border: 0;
    96	    border-radius: 4px;
    97	    background: #4a8cff;
    98	    color: #fff;
    99	    cursor: pointer;
   100	  }
   101	  .overlay[hidden] { display: none; }
   102	
   103	  /* Piece colours */
   104	  .p-I { background: #30c7e6; }
   105	  .p-O { background: #f2d33a; }
   106	  .p-T { background: #a35ee0; }
   107	  .p-S { background: #4ccf5a; }
   108	  .p-Z { background: #e8474a; }
   109	  .p-J { background: #3b6ee8; }
   110	  .p-L { background: #f09a2e; }
   111	</style>
