   113	<body>
   114	<div class="game">
   115	  <div class="board" data-testid="board" id="board">
   116	    <div class="overlay" id="overlay" hidden>
   117	      <div>Game over</div>
   118	      <button type="button" id="restart">Play again</button>
   119	    </div>
   120	  </div>
   121	  <div class="side">
   122	    <div class="box">
   123	      <div class="label">Score</div>
   124	      <div class="value" data-testid="score" id="score">0</div>
   125	    </div>
   126	    <div class="box">
   127	      <div class="label">Level</div>
   128	      <div class="value" data-testid="level" id="level">1</div>
   129	    </div>
   130	    <div class="box">
   131	      <div class="label">Lines</div>
   132	      <div class="value" data-testid="lines" id="lines">0</div>
   133	    </div>
   134	    <div class="box">
   135	      <div class="label">Next</div>
   136	      <div class="preview" id="preview"></div>
   137	    </div>
   138	    <div class="box help">
   139	      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>
   140	      <div><kbd>↑</kbd> <kbd>X</kbd> Rotate</div>
   141	      <div><kbd>↓</kbd> Soft drop</div>
   142	      <div><kbd>Space</kbd> Hard drop</div>
   143	    </div>
   144	  </div>
   145	</div>
   146	
   147	<script>
   148	(function () {
   149	  "use strict";
   150	
   151	  var ROWS = 20;
   152	  var COLS = 10;
   153	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
   154	
   155	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
   156	  var SHAPES = {
   157	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
   158	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
   159	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
   160	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
   161	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
   162	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
   163	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
   164	  };
   165	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
   166	
   167	  // The I piece has its own rotation states so it turns in place like the
   168	  // guideline piece, without ever reaching above the piece's own row.
   169	  var I_STATES = [
   170	    [[0, 0], [0, 1], [0, 2], [0, 3]],
   171	    [[0, 2], [1, 2], [2, 2], [3, 2]],
   172	    [[1, 0], [1, 1], [1, 2], [1, 3]],
   173	    [[0, 1], [1, 1], [2, 1], [3, 1]]
   174	  ];
   175	  // Sideways shifts tried, in order, when a rotated shape does not fit.
   176	  var KICKS = [0, -1, 1, -2, 2];
   177	
   178	  // Locking rule.
   179	  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
   180	  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
   181	
   182	  // Scoring rule. Points for a clear depend on how many rows go at once, times
   183	  // the current level. The table grows faster than the row count, so clearing
   184	  // rows together always beats clearing the same rows one at a time.
   185	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
   186	  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
   187	  var HARD_DROP_POINTS = 2; // per cell dropped
   188	
   189	  // ---- State ----
   190	  var board;       // ROWS x COLS array of piece letters or null
   191	  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
   192	  var queue;       // upcoming piece letters, soonest first
   193	  var bag;         // 7-bag for the random generator
   194	  var score, level, lines, status;
   195	  var timer = null;
   196	
   197	  function emptyBoard() {
   198	    var b = [];
   199	    for (var r = 0; r < ROWS; r++) {
   200	      var row = [];
   201	      for (var c = 0; c < COLS; c++) row.push(null);
   202	      b.push(row);
   203	    }
   204	    return b;
   205	  }
   206	
   207	  function randomPiece() {
   208	    if (!bag || bag.length === 0) {
   209	      bag = TYPES.slice();
   210	      for (var i = bag.length - 1; i > 0; i--) {
   211	        var j = Math.floor(Math.random() * (i + 1));
   212	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
   213	      }
   214	    }
   215	    return bag.pop();
   216	  }
   217	
   218	  function sanitizeQueue(q) {
   219	    if (!Array.isArray(q)) return [];
   220	    return q.map(function (x) { return String(x).toUpperCase(); })
   221	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
   222	  }
   223	
   224	  // Keep at least one upcoming piece so there is always something to preview.
   225	  function fillQueue() {
   226	    while (queue.length < 1) queue.push(randomPiece());
   227	  }
   228	
   229	  function pieceCells(p, dRow, dCol) {
   230	    var out = [];
   231	    for (var i = 0; i < p.shape.length; i++) {
   232	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
   233	    }
   234	    return out;
   235	  }
   236	
   237	  function fits(p, dRow, dCol) {
   238	    var cells = pieceCells(p, dRow, dCol);
   239	    for (var i = 0; i < cells.length; i++) {
   240	      var r = cells[i][0], c = cells[i][1];
   241	      if (c < 0 || c >= COLS || r >= ROWS) return false;
   242	      if (r >= 0 && board[r][c]) return false;
   243	    }
   244	    return true;
   245	  }
   246	
   247	  function spawn() {
   248	    fillQueue();
   249	    var type = queue.shift();
   250	    fillQueue();
   251	    var p = {
   252	      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
   253	      lockTicks: 0, lockResets: 0
   254	    };
   255	    if (!fits(p, 0, 0)) {
   256	      current = null;
   257	      status = "over";
   258	      stopTimer();
   259	      return;
   260	    }
   261	    current = p;
   262	  }
   263	
   264	  function lock() {
   265	    var cells = pieceCells(current, 0, 0);
   266	    for (var i = 0; i < cells.length; i++) {
   267	      var r = cells[i][0], c = cells[i][1];
   268	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
   269	    }
   270	    current = null;
   271	    clearLines();
   272	    spawn();
   273	  }
   274	
   275	  // Remove every full row; everything above drops down to fill the gap.
   276	  function clearLines() {
   277	    var kept = board.filter(function (row) {
   278	      return row.some(function (v) { return !v; });
   279	    });
   280	    var cleared = ROWS - kept.length;
   281	    if (cleared === 0) return;
   282	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
   283	    board = kept;
   284	    lines += cleared;
   285	    score += CLEAR_POINTS[cleared] * level;
   286	  }
   287	
   288	  // One gravity step. The real timer, tick() and soft drop all run this.
   289	  // If the piece cannot fall, the step counts one tick of lock delay instead.
   290	  // Returns true if the piece moved down.
   291	  function gravityStep() {
   292	    if (status !== "running" || !current) return false;
   293	    if (fits(current, 1, 0)) {
   294	      current.row += 1;
   295	      current.lockTicks = 0;
   296	      return true;
   297	    }
   298	    current.lockTicks += 1;
   299	    if (current.lockTicks >= LOCK_DELAY) lock();
   300	    return false;
   301	  }
   302	
   303	  function softDrop() {
   304	    if (gravityStep()) score += SOFT_DROP_POINTS;
   305	  }
   306	
   307	  // A sideways move while resting restarts the lock delay, up to
   308	  // MAX_LOCK_RESETS times per piece.
   309	  function move(dCol) {
   310	    if (status !== "running" || !current) return;
   311	    if (!fits(current, 0, dCol)) return;
   312	    var resting = !fits(current, 1, 0);
   313	    current.col += dCol;
   314	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
   315	      current.lockResets += 1;
   316	      current.lockTicks = 0;
   317	    }
   318	  }
   319	
   320	  function rotatedShape(p) {
   321	    var rot = (p.rot + 1) % 4;
   322	    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
   323	    var size = p.type === "O" ? 2 : 3;
   324	    return {
   325	      rot: rot,
   326	      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
   327	    };
   328	  }
   329	
   330	  // Rotate clockwise. If the turned shape does not fit, try shifting it
   331	  // sideways; if nothing fits, leave the piece exactly as it was.
   332	  function rotateCW() {
   333	    if (status !== "running" || !current) return;
   334	    var next = rotatedShape(current);
   335	    var trial = { row: current.row, col: current.col, shape: next.shape };
   336	    for (var i = 0; i < KICKS.length; i++) {
   337	      if (fits(trial, 0, KICKS[i])) {
   338	        current.col += KICKS[i];
   339	        current.rot = next.rot;
   340	        current.shape = next.shape;
   341	        return;
   342	      }
   343	    }
   344	  }
   345	
   346	  function hardDrop() {
   347	    if (status !== "running" || !current) return;
   348	    while (fits(current, 1, 0)) {
   349	      current.row += 1;
   350	      score += HARD_DROP_POINTS;
   351	    }
   352	    lock();
   353	  }
   354	
   355	  var ACTIONS = {
   356	    left: function () { move(-1); },
   357	    right: function () { move(1); },
   358	    rotateCW: rotateCW,
   359	    softDrop: softDrop,
   360	    hardDrop: hardDrop
   361	  };
   362	
   363	  // ---- Timer ----
   364	  function gravityInterval() {
   365	    return Math.max(100, 1000 - (level - 1) * 100);
   366	  }
   367	
   368	  function onTimer() {
   369	    gravityStep();
   370	    render();
   371	  }
   372	
   373	  function startTimer() {
   374	    stopTimer();
   375	    timer = setInterval(onTimer, gravityInterval());
   376	  }
   377	
   378	  function stopTimer() {
   379	    if (timer !== null) {
   380	      clearInterval(timer);
   381	      timer = null;
   382	    }
   383	  }
   384	
   385	  // ---- Rendering (synchronous) ----
   386	  var boardEl = document.getElementById("board");
   387	  var overlayEl = document.getElementById("overlay");
   388	  var scoreEl = document.getElementById("score");
   389	  var levelEl = document.getElementById("level");
   390	  var linesEl = document.getElementById("lines");
   391	  var previewEl = document.getElementById("preview");
   392	  var cellEls = [];
   393	  var previewEls = [];
   394	
   395	  (function buildDom() {
   396	    for (var r = 0; r < ROWS; r++) {
   397	      var row = [];
   398	      for (var c = 0; c < COLS; c++) {
   399	        var el = document.createElement("div");
   400	        el.className = "cell";
   401	        el.setAttribute("data-testid", "cell");
   402	        el.setAttribute("data-row", String(r));
   403	        el.setAttribute("data-col", String(c));
   404	        el.setAttribute("data-filled", "false");
   405	        el.setAttribute("data-piece", "");
   406	        boardEl.insertBefore(el, overlayEl);
   407	        row.push(el);
   408	      }
   409	      cellEls.push(row);
   410	    }
   411	    for (var i = 0; i < 8; i++) {
   412	      var m = document.createElement("div");
   413	      m.className = "mini";
   414	      previewEl.appendChild(m);
   415	      previewEls.push(m);
   416	    }
   417	  })();
   418	
   419	  function setCell(el, type) {
   420	    var piece = type || "";
   421	    if (el.getAttribute("data-piece") === piece) return;
   422	    el.className = piece ? "cell p-" + piece : "cell";
   423	    el.setAttribute("data-filled", piece ? "true" : "false");
   424	    el.setAttribute("data-piece", piece);
   425	  }
   426	
   427	  function render() {
   428	    var view = board.map(function (row) { return row.slice(); });
   429	    if (current) {
   430	      var cells = pieceCells(current, 0, 0);
   431	      for (var i = 0; i < cells.length; i++) {
   432	        var r = cells[i][0], c = cells[i][1];
   433	        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) view[r][c] = current.type;
   434	      }
   435	    }
   436	    for (var rr = 0; rr < ROWS; rr++) {
   437	      for (var cc = 0; cc < COLS; cc++) setCell(cellEls[rr][cc], view[rr][cc]);
   438	    }
   439	
   440	    scoreEl.textContent = String(score);
   441	    levelEl.textContent = String(level);
   442	    linesEl.textContent = String(lines);
   443	
   444	    for (var k = 0; k < previewEls.length; k++) previewEls[k].className = "mini";
   445	    var nextType = queue[0];
   446	    if (nextType) {
   447	      SHAPES[nextType].forEach(function (off) {
   448	        previewEls[off[0] * 4 + off[1]].className = "mini p-" + nextType;
   449	      });
   450	    }
   451	
   452	    overlayEl.hidden = status !== "over";
   453	  }
   454	
   455	  // ---- Game control ----
   456	  function newGame(q) {
   457	    board = emptyBoard();
   458	    bag = [];
   459	    queue = sanitizeQueue(q);
   460	    score = 0;
   461	    level = 1;
   462	    lines = 0;
   463	    status = "running";
   464	    current = null;
   465	    spawn();
   466	    if (status === "running") startTimer();
   467	    render();
   468	  }
   469	
   470	  function parseRows(rows) {
   471	    var b = emptyBoard();
   472	    if (!Array.isArray(rows)) return b;
   473	    for (var r = 0; r < ROWS && r < rows.length; r++) {
   474	      var line = String(rows[r]);
   475	      for (var c = 0; c < COLS && c < line.length; c++) {
   476	        var ch = line.charAt(c).toUpperCase();
   477	        b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
   478	      }
   479	    }
   480	    return b;
   481	  }
   482	
   483	  function boardToRows() {
   484	    return board.map(function (row) {
   485	      return row.map(function (v) { return v || "."; }).join("");
   486	    });
   487	  }
   488	
   489	  // ---- Keyboard ----
   490	  var KEYS = {
   491	    ArrowLeft: "left",
   492	    ArrowRight: "right",
   493	    ArrowUp: "rotateCW",
   494	    x: "rotateCW",
   495	    X: "rotateCW",
   496	    ArrowDown: "softDrop",
   497	    " ": "hardDrop",
   498	    Spacebar: "hardDrop"
   499	  };
   500	
   501	  document.addEventListener("keydown", function (e) {
   502	    if (status === "over" && e.key === "Enter") {
   503	      e.preventDefault();
   504	      newGame();
   505	      return;
   506	    }
   507	    var action = KEYS[e.key];
   508	    if (!action) return;
   509	    e.preventDefault();
   510	    ACTIONS[action]();
   511	    render();
   512	  });
   513	
   514	  document.getElementById("restart").addEventListener("click", function () {
   515	    newGame();
   516	  });
   517	
   518	  // ---- Test control surface ----
   519	  window.__tetris = {
   520	    newGame: function (q) { newGame(q); },
   521	    setQueue: function (q) {
   522	      queue = sanitizeQueue(q);
   523	      fillQueue();
   524	      render();
   525	    },
   526	    setBoard: function (rows) {
   527	      board = parseRows(rows);
   528	      render();
   529	    },
   530	    tick: function (n) {
   531	      var count = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
   532	      for (var i = 0; i < count; i++) gravityStep();
   533	      render();
   534	    },
   535	    input: function (action) {
   536	      var fn = ACTIONS[action];
   537	      if (!fn) return;
   538	      fn();
   539	      render();
   540	    },
   541	    getBoard: function () { return boardToRows(); },
   542	    getState: function () {
   543	      return {
   544	        current: current ? { type: current.type, cells: pieceCells(current, 0, 0) } : null,
   545	        next: queue.slice(),
   546	        score: score,
   547	        level: level,
   548	        lines: lines,
   549	        status: status
   550	      };
   551	    }
   552	  };
   553	
   554	  newGame();
   555	})();
   556	</script>
   557	</body>
   558	</html>
