   151	  var ROWS = 20;
   152	  var COLS = 10;
   153	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
   154	
   155	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
   156	  var SHAPES = {
   157	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
   158	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
   159	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
   160	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
   161	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
   162	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
   163	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
