   165	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
   166	
   167	  // The I piece has its own rotation states so it turns in place like the
   168	  // guideline piece, without ever reaching above the piece's own row.
   169	  var I_STATES = [
   170	    [[0, 0], [0, 1], [0, 2], [0, 3]],
   171	    [[0, 2], [1, 2], [2, 2], [3, 2]],
   172	    [[1, 0], [1, 1], [1, 2], [1, 3]],
   173	    [[0, 1], [1, 1], [2, 1], [3, 1]]
   174	  ];
   175	  // Sideways shifts tried, in order, when a rotated shape does not fit.
   176	  var KICKS = [0, -1, 1, -2, 2];
   177	
   178	  // Locking rule.
   179	  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
   180	  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
   181	
   182	  // Scoring rule. Points for a clear depend on how many rows go at once, times
   183	  // the current level. The table grows faster than the row count, so clearing
   184	  // rows together always beats clearing the same rows one at a time.
   185	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
   186	  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
   187	  var HARD_DROP_POINTS = 2; // per cell dropped
   188	
   189	  // ---- State ----
   190	  var board;       // ROWS x COLS array of piece letters or null
   191	  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
   192	  var queue;       // upcoming piece letters, soonest first
   193	  var bag;         // 7-bag for the random generator
   194	  var score, level, lines, status;
   195	  var timer = null;
