   197	  function emptyBoard() {
   198	    var b = [];
   199	    for (var r = 0; r < ROWS; r++) {
   200	      var row = [];
   201	      for (var c = 0; c < COLS; c++) row.push(null);
   202	      b.push(row);
   203	    }
   204	    return b;
   205	  }
   206	
   207	  function randomPiece() {
   208	    if (!bag || bag.length === 0) {
   209	      bag = TYPES.slice();
   210	      for (var i = bag.length - 1; i > 0; i--) {
   211	        var j = Math.floor(Math.random() * (i + 1));
   212	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
   213	      }
   214	    }
   215	    return bag.pop();
   216	  }
   217	
   218	  function sanitizeQueue(q) {
   219	    if (!Array.isArray(q)) return [];
   220	    return q.map(function (x) { return String(x).toUpperCase(); })
   221	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
   222	  }
   223	
   224	  // Keep at least one upcoming piece so there is always something to preview.
   225	  function fillQueue() {
   226	    while (queue.length < 1) queue.push(randomPiece());
   227	  }
   228	
   229	  function pieceCells(p, dRow, dCol) {
   230	    var out = [];
   231	    for (var i = 0; i < p.shape.length; i++) {
   232	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
   233	    }
   234	    return out;
   235	  }
   236	
   237	  function fits(p, dRow, dCol) {
   238	    var cells = pieceCells(p, dRow, dCol);
   239	    for (var i = 0; i < cells.length; i++) {
   240	      var r = cells[i][0], c = cells[i][1];
   241	      if (c < 0 || c >= COLS || r >= ROWS) return false;
   242	      if (r >= 0 && board[r][c]) return false;
   243	    }
   244	    return true;
   245	  }
   246	
   247	  function spawn() {
   248	    fillQueue();
   249	    var type = queue.shift();
   250	    fillQueue();
   251	    var p = {
   252	      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
   253	      lockTicks: 0, lockResets: 0
   254	    };
   255	    if (!fits(p, 0, 0)) {
   256	      current = null;
   257	      status = "over";
   258	      stopTimer();
   259	      return;
   260	    }
   261	    current = p;
   262	  }
   263	
   264	  function lock() {
   265	    var cells = pieceCells(current, 0, 0);
   266	    for (var i = 0; i < cells.length; i++) {
   267	      var r = cells[i][0], c = cells[i][1];
   268	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
   269	    }
   270	    current = null;
