   302	
   303	  function softDrop() {
   304	    if (gravityStep()) score += SOFT_DROP_POINTS;
   305	  }
   306	
   307	  // A sideways move while resting restarts the lock delay, up to
   308	  // MAX_LOCK_RESETS times per piece.
   309	  function move(dCol) {
   310	    if (status !== "running" || !current) return;
   311	    if (!fits(current, 0, dCol)) return;
   312	    var resting = !fits(current, 1, 0);
   313	    current.col += dCol;
   314	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
   315	      current.lockResets += 1;
   316	      current.lockTicks = 0;
   317	    }
   318	  }
   319	
   320	  function rotatedShape(p) {
   321	    var rot = (p.rot + 1) % 4;
   322	    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
   323	    var size = p.type === "O" ? 2 : 3;
   324	    return {
   325	      rot: rot,
   326	      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
   327	    };
   328	  }
   329	
   330	  // Rotate clockwise. If the turned shape does not fit, try shifting it
   331	  // sideways; if nothing fits, leave the piece exactly as it was.
   332	  function rotateCW() {
   333	    if (status !== "running" || !current) return;
   334	    var next = rotatedShape(current);
   335	    var trial = { row: current.row, col: current.col, shape: next.shape };
   336	    for (var i = 0; i < KICKS.length; i++) {
   337	      if (fits(trial, 0, KICKS[i])) {
   338	        current.col += KICKS[i];
   339	        current.rot = next.rot;
   340	        current.shape = next.shape;
   341	        return;
   342	      }
   343	    }
   344	  }
   345	
   346	  function hardDrop() {
   347	    if (status !== "running" || !current) return;
   348	    while (fits(current, 1, 0)) {
   349	      current.row += 1;
   350	      score += HARD_DROP_POINTS;
   351	    }
   352	    lock();
   353	  }
   354	
   355	  var ACTIONS = {
   356	    left: function () { move(-1); },
   357	    right: function () { move(1); },
   358	    rotateCW: rotateCW,
   359	    softDrop: softDrop,
   360	    hardDrop: hardDrop
   361	  };
   362	
   363	  // ---- Timer ----
   364	  function gravityInterval() {
   365	    return Math.max(100, 1000 - (level - 1) * 100);
   366	  }
   367	
   368	  function onTimer() {
   369	    gravityStep();
