   376	  }
   377	
   378	  function stopTimer() {
   379	    if (timer !== null) {
   380	      clearInterval(timer);
   381	      timer = null;
   382	    }
   383	  }
   384	
   385	  // ---- Rendering (synchronous) ----
   386	  var boardEl = document.getElementById("board");
   387	  var overlayEl = document.getElementById("overlay");
   388	  var scoreEl = document.getElementById("score");
   389	  var levelEl = document.getElementById("level");
   390	  var linesEl = document.getElementById("lines");
   391	  var previewEl = document.getElementById("preview");
   392	  var cellEls = [];
   393	  var previewEls = [];
   394	
   395	  (function buildDom() {
   396	    for (var r = 0; r < ROWS; r++) {
   397	      var row = [];
   398	      for (var c = 0; c < COLS; c++) {
   399	        var el = document.createElement("div");
   400	        el.className = "cell";
   401	        el.setAttribute("data-testid", "cell");
   402	        el.setAttribute("data-row", String(r));
   403	        el.setAttribute("data-col", String(c));
   404	        el.setAttribute("data-filled", "false");
   405	        el.setAttribute("data-piece", "");
   406	        boardEl.insertBefore(el, overlayEl);
   407	        row.push(el);
   408	      }
   409	      cellEls.push(row);
   410	    }
   411	    for (var i = 0; i < 8; i++) {
   412	      var m = document.createElement("div");
   413	      m.className = "mini";
   414	      previewEl.appendChild(m);
   415	      previewEls.push(m);
   416	    }
   417	  })();
   418	
   419	  function setCell(el, type) {
