   455	  // ---- Game control ----
   456	  function newGame(q) {
   457	    board = emptyBoard();
   458	    bag = [];
   459	    queue = sanitizeQueue(q);
   460	    score = 0;
   461	    level = 1;
   462	    lines = 0;
   463	    status = "running";
   464	    current = null;
   465	    spawn();
   466	    if (status === "running") startTimer();
